// ListOptions selects which template library release to list. Fields mirror
// DescribeOptions so callers can share configuration.
type ListOptions struct {
	Version string

	HTTP      *http.Client
	UserAgent string

	// Test overrides; production callers leave these zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

func (o *ListOptions) applyDefaults() {
	if o.Owner == "" {
		o.Owner = defaultTemplateOwner
	}
	if o.Repo == "" {
		o.Repo = defaultTemplateRepo
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// ListResult is the machine-readable view of a template library listing.
type ListResult struct {
	Owner     string   `json:"owner"`
	Repo      string   `json:"repo"`
	Version   string   `json:"version"`
	Templates []string `json:"templates"`
}

// List returns the names of the templates in the library at the requested
// version (or latest). Names are the directory names accepted by Describe
// and Create.
func List(ctx context.Context, opts ListOptions) (*ListResult, error) {
	opts.applyDefaults()

	gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
	if err != nil {
		return nil, err
	}
	names, err := gh.ListTemplates(ctx, opts.Owner, opts.Repo, tag)
	if err != nil {
		return nil, fmt.Errorf("list templates in %s/%s@%s: %w", opts.Owner, opts.Repo, tag, err)
	}
	sort.Strings(names)
	return &ListResult{
		Owner:     opts.Owner,
		Repo:      opts.Repo,
		Version:   tag,
		Templates: names,
	}, nil
}

package template

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"path/filepath"
	"sort"
)

// DescribeOptions selects which template release to inspect. Fields mirror
// CreateOptions for the create flow so callers can share configuration.
type DescribeOptions struct {
	Template  string // required; subdirectory in the templates repo holding template.yaml
	Version   string
	HTTP      *http.Client
	UserAgent string

	// Test overrides; production callers leave these zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

func (o *DescribeOptions) applyDefaults() {
	if o.Owner == "" {
		o.Owner = defaultTemplateOwner
	}
	if o.Repo == "" {
		o.Repo = defaultTemplateRepo
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// DescribeResult is the machine-readable view of a template manifest. The
// shape is stable and additive-only — Backstage's frontend renders the form
// from Parameters (a raw JSON Schema), so this contract is load-bearing.
type DescribeResult struct {
	Template    string            `json:"template"`
	Title       string            `json:"title,omitempty"`
	Description string            `json:"description,omitempty"`
	Tags        []string          `json:"tags,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
	Owner       string            `json:"owner"`
	Repo        string            `json:"repo"`
	Version     string            `json:"version"`
	Parameters  map[string]any    `json:"parameters"`

	// Dependencies lists the sibling templates this template scaffolds
	// alongside its own output (spec.dependencies).
	Dependencies []DependencySpec `json:"dependencies,omitempty"`

	// orderedFields preserves YAML declaration order for FormatText; YAML
	// order is lost once Parameters round-trips through JSON, so we keep it
	// here. Unexported so it stays out of the wire contract.
	orderedFields []FieldSpec
}

// Describe fetches the template tarball at the requested version (or latest)
// and returns its parsed template manifest. It performs the same fetch+extract
// path as Create but stops short of value resolution or rendering.
func Describe(ctx context.Context, opts DescribeOptions) (*DescribeResult, error) {
	opts.applyDefaults()
	if err := validateTemplateName(opts.Template); err != nil {
		return nil, err
	}

	gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
	if err != nil {
		return nil, err
	}

	templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-describe-*")
	if err != nil {
		return nil, err
	}
	defer cleanup()

	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, err
	}

	return &DescribeResult{
		Template:      tmpl.Metadata.Name,
		Title:         tmpl.Metadata.Title,
		Description:   tmpl.Metadata.Description,
		Tags:          tmpl.Metadata.Tags,
		Labels:        tmpl.Metadata.Labels,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		Version:       tag,
		Parameters:    tmpl.Spec.Parameters,
		Dependencies:  tmpl.Spec.Dependencies,
		orderedFields: tmpl.Fields(),
	}, nil
}

// FormatText writes a human-readable summary of the template to w. The
// machine-readable form is JSON-marshaled DescribeResult — callers needing
// stable parsing should use that instead.
func (r *DescribeResult) FormatText(w io.Writer) {
	title := r.Template
	if r.Title != "" {
		title = fmt.Sprintf("%s (%s)", r.Title, r.Template)
	}
	fmt.Fprintf(w, "%s @ %s/%s@%s\n", title, r.Owner, r.Repo, r.Version)
	if r.Description != "" {
		fmt.Fprintf(w, "\n%s\n", r.Description)
	}
	if len(r.Tags) > 0 {
		fmt.Fprintf(w, "\nTags: %v\n", r.Tags)
	}
	if len(r.Dependencies) > 0 {
		fmt.Fprintln(w, "\nScaffolds alongside (skipped when already present):")
		for _, d := range r.Dependencies {
			fmt.Fprintf(w, "  %s -> ../%s\n", d.Template, d.Output)
		}
	}

	fields := r.orderedFields
	if fields == nil {
		// Result was JSON-unmarshaled by a downstream consumer; declaration
		// order is gone. Fall back to alphabetical so output is at least
		// deterministic.
		fields = fieldsFromSchema(r.Parameters)
	}
	if len(fields) > 0 {
		fmt.Fprintln(w, "\nParameters:")
		for _, f := range fields {
			marker := " "
			if f.Required {
				marker = "*"
			}
			label := f.Name
			if f.Title != "" {
				label = fmt.Sprintf("%s — %s", f.Name, f.Title)
			}
			fmt.Fprintf(w, "  %s %s [%s]\n", marker, label, f.Type)
			if f.Description != "" {
				fmt.Fprintf(w, "      %s\n", f.Description)
			}
			if f.Default != nil {
				fmt.Fprintf(w, "      default: %v\n", f.Default)
			}
			if len(f.Enum) > 0 {
				fmt.Fprintf(w, "      values: %v\n", f.Enum)
			}
			if f.Pattern != "" {
				fmt.Fprintf(w, "      pattern: %s\n", f.Pattern)
			}
		}
		fmt.Fprintln(w, "  (* = required)")
	}
}

// fieldsFromSchema returns FieldSpecs from a raw parameters block. Unlike
// Template.Fields it has no declaration-order information, so it falls back
// to alphabetical order for stable output.
func fieldsFromSchema(parameters map[string]any) []FieldSpec {
	props, _ := parameters["properties"].(map[string]any)
	if props == nil {
		return nil
	}
	required := map[string]bool{}
	if list, ok := parameters["required"].([]any); ok {
		for _, r := range list {
			if s, ok := r.(string); ok {
				required[s] = true
			}
		}
	}
	names := make([]string, 0, len(props))
	for k := range props {
		names = append(names, k)
	}
	sort.Strings(names)
	out := make([]FieldSpec, 0, len(names))
	for _, name := range names {
		raw, _ := props[name].(map[string]any)
		out = append(out, fieldFromSchema(name, raw, required[name]))
	}
	return out
}

package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type CreateOptions struct {
	Template   string // required; subdirectory in the templates repo holding template.yaml + skeleton/
	OutputDir  string
	Version    string
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Test overrides. Production callers leave these zero-valued; the CLI
	// always targets the official template library at integrio-intropy/intropy-templates.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json is
// set. It is the contract chained scaffolder steps consume; field names are
// stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`

	// Dependencies reports what happened to each spec.dependencies entry
	// (including transitive ones): rendered now ("created") or already
	// present ("exists").
	Dependencies []DependencyResult `json:"dependencies,omitempty"`
}

func (o *CreateOptions) applyDefaults() {
	if o.Owner == "" {
		o.Owner = defaultTemplateOwner
	}
	if o.Repo == "" {
		o.Repo = defaultTemplateRepo
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full scaffold: resolve release, download tarball, extract,
// load manifest, resolve values (with optional interactive prompting), render.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if err := validateCreateOptions(opts); err != nil {
		return err
	}

	gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
	if err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)

	templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-template-*")
	if err != nil {
		return err
	}
	defer cleanup()

	tmpl, values, err := prepareCreateTemplate(templateRoot, opts)
	if err != nil {
		return err
	}

	if err := renderCreateOutput(templateRoot, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, opts.Owner, opts.Repo, tag, opts.Template)

	// Dependencies come from the same extracted tarball, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(tmpl, values, opts.OutputDir, &depContext{
		repoRoot: filepath.Dir(templateRoot),
		owner:    opts.Owner,
		repo:     opts.Repo,
		version:  tag,
		stderr:   opts.Stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return err
	}

	// The template field is the repo directory name (opts.Template), not
	// tmpl.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(opts.OutputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      opts.Template,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(tmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(tmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
		DependsOn:     depRecords,
	}); err != nil {
		return err
	}

	return maybeWriteCreateResult(opts, tmpl, values, tag, depResults)
}

func validateCreateOptions(opts CreateOptions) error {
	if err := validateTemplateName(opts.Template); err != nil {
		return err
	}
	if opts.OutputDir == "" {
		return errors.New("--out-dir is required")
	}
	return nil
}

func prepareCreateTemplate(templateRoot string, opts CreateOptions) (*Template, map[string]any, error) {
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, nil, err
	}

	prompter := selectPrompter(&opts)
	values, err := Resolve(tmpl, opts.Files, opts.Stdin, opts.SetValues, prompter)
	if err != nil {
		return nil, nil, err
	}
	return tmpl, values, nil
}

func renderCreateOutput(templateRoot, templateName, outputDir string, force bool, values map[string]any) error {
	skelRoot := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
	}
	if err := ensureOutputDir(outputDir, force); err != nil {
		return err
	}
	return Render(skelRoot, outputDir, values)
}

func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string, deps []DependencyResult) error {
	if opts.OutputJSON == "" {
		return nil
	}

	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:     tmpl.Metadata.Name,
		Owner:        opts.Owner,
		Repo:         opts.Repo,
		Version:      tag,
		OutputDir:    absOut,
		Values:       values,
		Dependencies: deps,
	}
	if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if path == "-" {
		_, err := stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

// EnsureOutputDir creates dir if missing and refuses to render into a
// non-empty directory unless force is set.
func EnsureOutputDir(dir string, force bool) error {
	return ensureOutputDir(dir, force)
}

func ensureOutputDir(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return os.MkdirAll(dir, 0o755)
	case err != nil:
		return err
	case !info.IsDir():
		return fmt.Errorf("--output %s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 && !force {
		return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
	}
	return nil
}

// validateTemplateName rejects empty names and anything that could escape the
// extracted tarball root via filepath.Join (separators, parent refs, hidden
// directories). The template argument is user input that we turn directly into
// a path segment, so it has to be sanitized.
func validateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name is required")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid template name %q", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
	}
	return nil
}

func selectPrompter(opts *CreateOptions) Prompter {
	return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
}

// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
// noInput is false and stdin is a real terminal. In CI / piped contexts it
// returns nil, so Resolve reports a clean "missing required parameter(s)"
// error instead of hanging on a read.
func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
	if noInput {
		return nil
	}
	f, ok := stdin.(*os.File)
	if !ok || !isTerminal(f.Fd()) {
		return nil
	}
	return NewStdinPrompter(stdin, out)
}

package template

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
)

// DefaultLibrary reports the official template library the CLI targets.
//
// Callers outside this package need it to describe what they fetched; the
// constants themselves stay unexported so defaults_test.go remains the one place
// a change to the library source has to be acknowledged.
func DefaultLibrary() (owner, repo string) {
	return defaultTemplateOwner, defaultTemplateRepo
}

// LibraryOptions selects which template library to fetch.
type LibraryOptions struct {
	// Version pins a release tag. Empty resolves the latest release.
	Version string

	HTTP      *http.Client
	UserAgent string
	Stderr    io.Writer

	// Test overrides. Production callers leave these zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// Library is a template library extracted on disk at one resolved version.
//
// It exists so a caller rendering several templates pays for one download and
// gets one version across all of them — a component's manifests and its system's
// shared manifests drifting apart by a release would be a subtle, ugly bug. It
// also keeps the on-disk layout of a template package private to this package.
//
// The caller owns the returned Library and must Close it.
type Library struct {
	Owner   string
	Repo    string
	Version string

	root    string
	cleanup func()
}

// FetchLibrary resolves the release tag, downloads the library tarball and
// extracts it.
func FetchLibrary(ctx context.Context, opts LibraryOptions) (*Library, error) {
	owner, repo := DefaultLibrary()
	if opts.Owner != "" {
		owner = opts.Owner
	}
	if opts.Repo != "" {
		repo = opts.Repo
	}
	userAgent := opts.UserAgent
	if userAgent == "" {
		userAgent = "intropy-cli"
	}

	gh := newConfiguredGitHub(opts.HTTP, userAgent, opts.GitHubBaseURL)
	tag, err := gh.ResolveTag(ctx, owner, repo, opts.Version)
	if err != nil {
		return nil, err
	}
	if opts.Stderr != nil {
		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", owner, repo, tag)
	}

	rc, err := gh.Tarball(ctx, owner, repo, tag)
	if err != nil {
		return nil, err
	}
	defer rc.Close()

	tmpDir, err := os.MkdirTemp("", "intropy-library-*")
	if err != nil {
		return nil, err
	}
	cleanup := func() { _ = os.RemoveAll(tmpDir) }
	if err := ExtractTarGz(rc, tmpDir); err != nil {
		cleanup()
		return nil, err
	}
	return &Library{Owner: owner, Repo: repo, Version: tag, root: tmpDir, cleanup: cleanup}, nil
}

// Close removes the extracted copy.
func (l *Library) Close() {
	if l != nil && l.cleanup != nil {
		l.cleanup()
	}
}

// Ref describes the fetched library, for logs and result records.
func (l *Library) Ref() string {
	return fmt.Sprintf("%s/%s@%s", l.Owner, l.Repo, l.Version)
}

// Open loads one template's manifest and returns it with its skeleton root.
//
// The name is validated as a single path segment before it is joined, because it
// is user input turned into a path inside the extracted tarball.
func (l *Library) Open(name string) (*Template, string, error) {
	if err := validateTemplateName(name); err != nil {
		return nil, "", err
	}
	templateRoot := filepath.Join(l.root, name)
	if info, err := os.Stat(templateRoot); err != nil || !info.IsDir() {
		return nil, "", fmt.Errorf("template %q not found in %s", name, l.Ref())
	}
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, "", fmt.Errorf("%s in %s: %w", name, l.Ref(), err)
	}
	skeleton := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skeleton); err != nil || !info.IsDir() {
		return nil, "", fmt.Errorf("template %q is missing %s/ directory", name, templateSkeletonDir)
	}
	return tmpl, skeleton, nil
}

package template

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"text/template"

	"github.com/Masterminds/sprig/v3"
	"github.com/santhosh-tekuri/jsonschema/v5"
	"gopkg.in/yaml.v3"
)

// StdinValuesPath is the sentinel a caller may pass in the values-file list
// to signal "read a single values document from this reader". It mirrors the
// `-f -` idiom used by helm, kubectl, and curl.
const StdinValuesPath = "-"

// Resolve produces the final value map by layering, in order:
//
//	defaults declared in spec.parameters.properties[*].default
//	--values files (in supplied order; "-" reads one doc from stdin)
//	--set flags (string values, coerced to declared JSON Schema types)
//	prompts for required parameters still missing (when prompter != nil)
//
// stdin is consumed at most once across the files list; passing "-" twice is
// an error. The merged map is then validated against the JSON Schema in
// spec.parameters. Finally, every entry in spec.values is rendered as a Go
// text/template (with sprig) against the merged map and added under its key.
// A spec.values key that collides with a parameter name is rejected.
func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveLayered(t, nil, files, stdin, sets, prompter)
}

// ResolveLayered is Resolve with an extra base layer that sits between the
// spec.parameters defaults and the --values files. Callers use it to seed
// values from an earlier resolution (e.g. a committed scaffold record) so
// they take effect without re-prompting but still yield to explicit
// --values / --set input.
func ResolveLayered(t *Template, base map[string]any, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	fields := t.Fields()
	byName := indexFields(fields)
	out := map[string]any{}

	applyDefaultValues(fields, out)
	for k, v := range base {
		out[k] = coerceKnownFieldValue(k, v, byName)
	}
	if err := applyValuesFiles(files, stdin, out, byName); err != nil {
		return nil, err
	}
	applySetValues(sets, out, byName)
	if err := promptForMissingRequired(fields, out, prompter); err != nil {
		return nil, err
	}
	if err := validateSchema(t.Spec.Parameters, out); err != nil {
		return nil, fmt.Errorf("parameter validation: %w", err)
	}
	if err := renderDerivedValues(t.Spec.Values, out, byName); err != nil {
		return nil, err
	}

	return out, nil
}

func applyDefaultValues(fields []FieldSpec, values map[string]any) {
	for _, f := range fields {
		if f.Default != nil {
			values[f.Name] = f.Default
		}
	}
}

func applyValuesFiles(files []string, stdin io.Reader, values map[string]any, byName map[string]FieldSpec) error {
	stdinUsed := false
	for _, path := range files {
		if path == StdinValuesPath {
			if stdinUsed {
				return fmt.Errorf("--values - specified more than once (stdin can only be read once)")
			}
			if stdin == nil {
				return fmt.Errorf("--values - specified but no stdin reader provided")
			}
			data, err := io.ReadAll(stdin)
			if err != nil {
				return fmt.Errorf("read values from stdin: %w", err)
			}
			if err := mergeValuesBytes(data, "stdin", values, byName); err != nil {
				return err
			}
			stdinUsed = true
			continue
		}
		if err := mergeValuesFile(path, values, byName); err != nil {
			return err
		}
	}
	return nil
}

func applySetValues(sets map[string]any, values map[string]any, byName map[string]FieldSpec) {
	for k, v := range sets {
		values[k] = coerceKnownFieldValue(k, v, byName)
	}
}

func promptForMissingRequired(fields []FieldSpec, values map[string]any, prompter Prompter) error {
	missing := missingRequired(fields, values)
	if len(missing) == 0 {
		return nil
	}
	if prompter == nil {
		names := make([]string, 0, len(missing))
		for _, f := range missing {
			names = append(names, f.Name)
		}
		return fmt.Errorf("missing required parameter(s): %s", strings.Join(names, ", "))
	}
	for _, f := range missing {
		ans, err := prompter.Prompt(f)
		if err != nil {
			return err
		}
		if isEmpty(ans) {
			return fmt.Errorf("required parameter %q has no value", f.Name)
		}
		values[f.Name] = ans
	}
	return nil
}

func renderDerivedValues(derived map[string]string, values map[string]any, byName map[string]FieldSpec) error {
	for k, expr := range derived {
		if _, collides := byName[k]; collides {
			return fmt.Errorf("spec.values.%s collides with a parameter of the same name", k)
		}
		rendered, err := renderExpr(expr, values)
		if err != nil {
			return fmt.Errorf("spec.values.%s: %w", k, err)
		}
		values[k] = rendered
	}
	return nil
}

func mergeValuesFile(path string, into map[string]any, byName map[string]FieldSpec) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read values file %s: %w", path, err)
	}
	return mergeValuesBytes(data, path, into, byName)
}

func mergeValuesBytes(data []byte, source string, into map[string]any, byName map[string]FieldSpec) error {
	var fileVals map[string]any
	if err := yaml.Unmarshal(data, &fileVals); err != nil {
		return fmt.Errorf("parse values from %s: %w", source, err)
	}
	for k, v := range fileVals {
		into[k] = coerceKnownFieldValue(k, v, byName)
	}
	return nil
}

func coerceKnownFieldValue(name string, value any, byName map[string]FieldSpec) any {
	field, ok := byName[name]
	if !ok {
		return value
	}
	str, ok := value.(string)
	if !ok {
		return value
	}
	return coerce(str, field.Type)
}

func indexFields(fields []FieldSpec) map[string]FieldSpec {
	m := make(map[string]FieldSpec, len(fields))
	for _, f := range fields {
		m[f.Name] = f
	}
	return m
}

func missingRequired(fields []FieldSpec, values map[string]any) []FieldSpec {
	var missing []FieldSpec
	for _, f := range fields {
		if !f.Required {
			continue
		}
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		missing = append(missing, f)
	}
	return missing
}

func validateSchema(schema map[string]any, values map[string]any) error {
	raw, err := json.Marshal(schema)
	if err != nil {
		return err
	}
	c := jsonschema.NewCompiler()
	if err := c.AddResource("inline://params.json", bytes.NewReader(raw)); err != nil {
		return err
	}
	s, err := c.Compile("inline://params.json")
	if err != nil {
		return err
	}
	return s.Validate(values)
}

// compileExpr parses a Go text/template string with sprig helpers and
// missingkey=error, so an undefined value name is a loud failure rather than a
// silently empty string. Separate from renderExpr because spec.files rules are
// parsed at load time to reject a syntax error early, and only evaluated later
// once values exist.
func compileExpr(expr string) (*template.Template, error) {
	return template.New("expr").
		Funcs(sprig.TxtFuncMap()).
		Option("missingkey=error").
		Parse(expr)
}

// renderExpr renders a Go text/template string (with sprig) against the
// supplied data map. Used for spec.values entries and spec.files conditions.
func renderExpr(expr string, data map[string]any) (string, error) {
	tmpl, err := compileExpr(expr)
	if err != nil {
		return "", err
	}
	var sb strings.Builder
	if err := tmpl.Execute(&sb, data); err != nil {
		return "", err
	}
	return sb.String(), nil
}

// ParseSets converts ["key=value", ...] into a map. Values stay as strings;
// Resolve coerces them to the JSON Schema type when the key matches a known
// parameter.
func ParseSets(items []string) (map[string]any, error) {
	out := map[string]any{}
	for _, item := range items {
		i := strings.Index(item, "=")
		if i <= 0 {
			return nil, fmt.Errorf("invalid --set %q (expected key=value)", item)
		}
		out[item[:i]] = item[i+1:]
	}
	return out, nil
}

func isEmpty(v any) bool {
	switch t := v.(type) {
	case nil:
		return true
	case string:
		return t == ""
	default:
		return false
	}
}

import { useCallback, useEffect, useState } from 'react'
import { api, type DeployState, type Integration, type IntegrationDetail } from './api'
import { Sidebar } from './components/Sidebar'
import { DetailPanel } from './components/DetailPanel'
import { FlowView } from './components/FlowView'
import { DarkModeIcon, LightModeIcon, SystemThemeIcon } from './icons'

const SIDEBAR_COLLAPSED_KEY = 'intropy.sidebar.collapsed'
const THEME_KEY = 'intropy.theme'

type View = 'catalog' | 'flow'

const VIEWS: { id: View; label: string }[] = [
  { id: 'catalog', label: 'Integration Catalog' },
  { id: 'flow', label: 'Integration Flow' },
]

// Theme preference cycles light → dark → system. "system" follows the OS,
// resolved to a concrete light/dark value that drives both data-theme (CSS)
// and the flow canvas colorMode.
type ThemePref = 'light' | 'dark' | 'system'
const THEME_ORDER: ThemePref[] = ['light', 'dark', 'system']
const THEME_META: Record<ThemePref, { Icon: typeof LightModeIcon; label: string }> = {
  light: { Icon: LightModeIcon, label: 'Light' },
  dark: { Icon: DarkModeIcon, label: 'Dark' },
  system: { Icon: SystemThemeIcon, label: 'System' },
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolveTheme(pref: ThemePref): 'light' | 'dark' {
  return pref === 'system' ? (prefersDark() ? 'dark' : 'light') : pref
}

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [detail, setDetail] = useState<IntegrationDetail | null>(null)
  const [deployState, setDeployState] = useState<DeployState | null>(null)
  const [deployLoading, setDeployLoading] = useState(false)
  const [deployRefreshing, setDeployRefreshing] = useState(false)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)
  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === 'true',
  )
  const [view, setView] = useState<View>('catalog')
  const [theme, setTheme] = useState<ThemePref>(
    () => (localStorage.getItem(THEME_KEY) as ThemePref | null) ?? 'system',
  )
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() =>
    resolveTheme(theme),
  )

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed))
  }, [collapsed])

  // Apply the theme to <html> and track the resolved value. In system mode,
  // also follow live OS changes; explicit modes ignore them.
  useEffect(() => {
    localStorage.setItem(THEME_KEY, theme)
    const apply = () => {
      const resolved = resolveTheme(theme)
      document.documentElement.dataset.theme = resolved
      setResolvedTheme(resolved)
    }
    apply()
    if (theme !== 'system') return
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [theme])

  const cycleTheme = () =>
    setTheme((t) => THEME_ORDER[(THEME_ORDER.indexOf(t) + 1) % THEME_ORDER.length])

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  useEffect(() => {
    if (!selected) {
      setDetail(null)
      return
    }
    setDetail(null)
    api
      .getIntegration(selected)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [selected])

  // Deployment state loads on its own, because it costs its own thing: reading
  // it refreshes a GitOps checkout over the network, while the detail above is
  // local files. Keeping them apart lets the panel render straight away.
  //
  // A failed lookup is not an error banner: the reason travels inside the state
  // and belongs in the Deployment section, next to the Refresh that retries it.
  useEffect(() => {
    if (!selected) {
      setDeployState(null)
      return
    }
    setDeployState(null)
    setDeployLoading(true)
    let current = true
    api
      .deployState(selected)
      .then((s) => {
        if (current) setDeployState(s)
      })
      .catch((e: unknown) => {
        if (current) setDeployState({ error: errText(e), readAt: new Date().toISOString() })
      })
      .finally(() => {
        if (current) setDeployLoading(false)
      })
    // Selecting another integration while this is in flight must not let the
    // slower answer land on the newer selection.
    return () => {
      current = false
    }
  }, [selected])

  const refreshDeploy = useCallback(() => {
    if (!selected) return
    setDeployRefreshing(true)
    api
      .refreshDeployState(selected)
      .then(setDeployState)
      .catch((e: unknown) =>
        setDeployState({ error: errText(e), readAt: new Date().toISOString() }),
      )
      .finally(() => setDeployRefreshing(false))
  }, [selected])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        <nav className="nav">
          {VIEWS.map((v) => (
            <button
              key={v.id}
              className={`nav-item${view === v.id ? ' active' : ''}`}
              onClick={() => setView(v.id)}
              aria-current={view === v.id ? 'page' : undefined}
            >
              {v.label}
            </button>
          ))}
        </nav>
        <div className="topbar-end">
          {version && <span className="version">{version}</span>}
          <ThemeToggle theme={theme} onCycle={cycleTheme} />
        </div>
      </header>

      <div className="layout">
        {view === 'catalog' && (
          <Sidebar
            integrations={integrations}
            selected={selected}
            onSelect={setSelected}
            collapsed={collapsed}
            onToggle={() => setCollapsed((c) => !c)}
          />
        )}
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          {view === 'catalog' ? (
            <DetailPanel
              detail={detail}
              hasSelection={!!selected}
              deploy={{
                state: deployState,
                loading: deployLoading,
                refreshing: deployRefreshing,
                onRefresh: refreshDeploy,
              }}
            />
          ) : (
            <FlowView selected={selected} onSelect={setSelected} theme={resolvedTheme} />
          )}
        </main>
      </div>
    </div>
  )
}

// ThemeToggle cycles the theme preference. The current mode's glyph and a
// title communicate both the active choice and that clicking advances it.
function ThemeToggle({ theme, onCycle }: { theme: ThemePref; onCycle: () => void }) {
  const { Icon, label } = THEME_META[theme]
  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={onCycle}
      title={`Theme: ${label} (click to change)`}
      aria-label={`Theme: ${label}. Click to change.`}
    >
      <Icon className="icon" aria-hidden />
    </button>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

