package template

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
)

const (
	defaultTemplateOwner = "integrio-intropy"
	defaultTemplateRepo  = "intropy-templates"
	templateManifestName = "template.yaml"
	templateSkeletonDir  = "skeleton"
	githubAPIBaseURL     = "https://api.github.com"
)

// GitHub talks to a GitHub-compatible API. BaseURL is overridable for tests.
type GitHub struct {
	BaseURL   string
	HTTP      *http.Client
	Token     string
	UserAgent string
}

func newGitHub(client *http.Client, userAgent string) *GitHub {
	if client == nil {
		client = http.DefaultClient
	}
	return &GitHub{
		BaseURL:   githubAPIBaseURL,
		HTTP:      client,
		Token:     os.Getenv("GITHUB_TOKEN"),
		UserAgent: userAgent,
	}
}

// NewGitHubClient creates a configured GitHub client for external callers.
func NewGitHubClient(client *http.Client, userAgent, baseURL string) *GitHub {
	gh := newGitHub(client, userAgent)
	if baseURL != "" {
		gh.BaseURL = baseURL
	}
	return gh
}

func newConfiguredGitHub(client *http.Client, userAgent, baseURL string) *GitHub {
	return NewGitHubClient(client, userAgent, baseURL)
}

func resolveReleaseTag(ctx context.Context, gh *GitHub, owner, repo, requestedTag string) (string, error) {
	return gh.ResolveTag(ctx, owner, repo, requestedTag)
}

// ResolveTag returns requestedTag as-is when set, otherwise the latest
// release tag for owner/repo.
func (g *GitHub) ResolveTag(ctx context.Context, owner, repo, requestedTag string) (string, error) {
	if requestedTag != "" {
		return requestedTag, nil
	}
	return g.LatestTag(ctx, owner, repo)
}

// DownloadTemplate fetches the repo tarball at tag, extracts it to a temp
// dir (created with tempPattern), and returns the path of the named template
// subdirectory plus a cleanup func that removes the temp dir.
func DownloadTemplate(ctx context.Context, gh *GitHub, owner, repo, tag, templateName, tempPattern string) (string, func(), error) {
	return downloadTemplate(ctx, gh, owner, repo, tag, templateName, tempPattern)
}

func downloadTemplate(ctx context.Context, gh *GitHub, owner, repo, tag, templateName, tempPattern string) (string, func(), error) {
	rc, err := gh.Tarball(ctx, owner, repo, tag)
	if err != nil {
		return "", nil, err
	}
	defer rc.Close()

	tmpDir, err := os.MkdirTemp("", tempPattern)
	if err != nil {
		return "", nil, err
	}
	cleanup := func() { _ = os.RemoveAll(tmpDir) }

	if err := ExtractTarGz(rc, tmpDir); err != nil {
		cleanup()
		return "", nil, err
	}

	templateRoot := filepath.Join(tmpDir, templateName)
	if info, err := os.Stat(templateRoot); err != nil || !info.IsDir() {
		cleanup()
		return "", nil, fmt.Errorf("template %q not found in %s/%s@%s", templateName, owner, repo, tag)
	}
	return templateRoot, cleanup, nil
}

// LatestTag returns the tag_name of the most recent release for owner/repo.
func (g *GitHub) LatestTag(ctx context.Context, owner, repo string) (string, error) {
	u := fmt.Sprintf("%s/repos/%s/%s/releases/latest", g.BaseURL, owner, repo)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	g.addCommonHeaders(req)

	resp, err := g.HTTP.Do(req)
	if err != nil {
		return "", fmt.Errorf("github releases: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return "", fmt.Errorf("github releases: %s: %s", resp.Status, string(body))
	}
	var rel struct {
		TagName string `json:"tag_name"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&rel); err != nil {
		return "", fmt.Errorf("decode release: %w", err)
	}
	if rel.TagName == "" {
		return "", fmt.Errorf("github releases: empty tag_name")
	}
	return rel.TagName, nil
}

// Tarball returns a streaming reader of the gzipped tar for owner/repo at tag.
// The caller must Close the returned ReadCloser.
func (g *GitHub) Tarball(ctx context.Context, owner, repo, tag string) (io.ReadCloser, error) {
	u := fmt.Sprintf("%s/repos/%s/%s/tarball/%s", g.BaseURL, owner, repo, tag)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return nil, err
	}
	g.addCommonHeaders(req)

	resp, err := g.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("download tarball: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		resp.Body.Close()
		return nil, fmt.Errorf("download tarball: %s: %s", resp.Status, string(body))
	}
	return resp.Body, nil
}

// ListTemplates returns the names of template directories at the root of
// the templates repository at the given ref (a release tag). An empty ref
// lists the default branch.
func (g *GitHub) ListTemplates(ctx context.Context, owner, repo, ref string) ([]string, error) {
	if owner == "" {
		owner = defaultTemplateOwner
	}
	if repo == "" {
		repo = defaultTemplateRepo
	}
	u := fmt.Sprintf("%s/repos/%s/%s/contents/", g.BaseURL, owner, repo)
	if ref != "" {
		u += "?ref=" + url.QueryEscape(ref)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	g.addCommonHeaders(req)

	resp, err := g.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("list contents: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return nil, fmt.Errorf("list contents: %s: %s", resp.Status, string(body))
	}

	var entries []struct {
		Name string `json:"name"`
		Type string `json:"type"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&entries); err != nil {
		return nil, fmt.Errorf("decode contents: %w", err)
	}

	var dirs []string
	for _, e := range entries {
		if e.Type == "dir" {
			dirs = append(dirs, e.Name)
		}
	}
	return dirs, nil
}

func (g *GitHub) addCommonHeaders(req *http.Request) {
	if g.UserAgent != "" {
		req.Header.Set("User-Agent", g.UserAgent)
	}
	if g.Token != "" {
		req.Header.Set("Authorization", "Bearer "+g.Token)
	}
}

package main

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"golang.org/x/term"
)

// The official Intropy skills collection offered by `int create`.
const (
	defaultSkillsCollectionAlias = "intropy"
	defaultSkillsCollectionRef   = "harbor.intropy.io/skills/index:latest"
)

// skillsCollectionRef returns the collection to offer, overridable via
// INTROPY_SKILLS_COLLECTION (useful for testing against a local registry).
func skillsCollectionRef() string {
	return cmp.Or(os.Getenv("INTROPY_SKILLS_COLLECTION"), defaultSkillsCollectionRef)
}

// decideInstallSkills is the pure gating logic for the post-scaffold skills
// install: --skip-install-skills forces a no and --install-skills forces a
// yes, both without prompting; otherwise --no-input and non-terminal stdin
// skip, and an interactive session gets a [Y/n] prompt (default yes).
func decideInstallSkills(force, skip, noInput bool, in io.Reader, errW io.Writer) (bool, error) {
	if skip {
		return false, nil
	}
	if force {
		return true, nil
	}
	if noInput {
		return false, nil
	}
	f, ok := in.(*os.File)
	if !ok || !term.IsTerminal(int(f.Fd())) {
		return false, nil
	}
	return confirmInstallSkills(in, errW)
}

// maybeInstallSkills applies decideInstallSkills and, on yes, does the
// equivalent of `skills collection add` plus `skills add` for every skill in
// the collection. On no, it prints how to install later — unless the skip
// was the explicit --skip-install-skills, where a hint would just be noise.
func maybeInstallSkills(ctx context.Context, in io.Reader, errW io.Writer, force, skip, noInput bool, outputDir string) error {
	install, err := decideInstallSkills(force, skip, noInput, in, errW)
	if err != nil {
		return err
	}
	ref := skillsCollectionRef()
	if !install {
		if !skip {
			fmt.Fprintf(errW, "skills not installed — run 'intropy skills collection add --name %s --ref %s' in the integration later\n",
				defaultSkillsCollectionAlias, ref)
		}
		return nil
	}

	project, err := skillProjectAt(outputDir)
	if err != nil {
		return err
	}
	client, err := newSkillRegistry()
	if err != nil {
		return err
	}
	installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
	adder := skill.NewAdder(client, installer, project)

	entries, err := skill.NewCollectionInstaller(client, adder, project).
		InstallAll(ctx, defaultSkillsCollectionAlias, ref)
	if err != nil {
		return err
	}
	for _, e := range entries {
		fmt.Fprintf(errW, "  installed %s @ %s (%s)\n", e.Name, e.Source.Tag, e.Path)
	}
	fmt.Fprintf(errW, "installed %d skill(s) from %s\n", len(entries), ref)
	return nil
}

// confirmInstallSkills renders a [Y/n] prompt (default yes) and reads the
// answer. EOF counts as a decline, not an error.
func confirmInstallSkills(in io.Reader, out io.Writer) (bool, error) {
	v, err := template.NewStdinPrompter(in, out).Prompt(template.FieldSpec{
		Name:    "install-skills",
		Title:   "Install agent skills into .agents/skills?",
		Type:    "boolean",
		Default: true,
	})
	if errors.Is(err, io.EOF) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	b, ok := v.(bool)
	return ok && b, nil
}

// skillProjectAt returns the skills project rooted exactly at dir, creating an
// empty skills.json there if the template didn't ship one. Unlike
// resolveOrBootstrapProject it never walks up: the scaffolded integration is
// its own skills project even when created inside a larger repo.
func skillProjectAt(dir string) (*skill.Project, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, err
	}
	p := &skill.Project{Root: abs}
	if _, err := os.Stat(p.ManifestPath()); err == nil {
		return p, nil
	} else if !os.IsNotExist(err) {
		return nil, err
	}
	if err := p.SaveManifest(&skill.Manifest{Skills: []skill.ManifestEntry{}}); err != nil {
		return nil, fmt.Errorf("bootstrap skills.json: %w", err)
	}
	return p, nil
}

import type { DeployState, EnvironmentStatus, StatusResult } from '../api'
import { Section } from './DetailPanel'
import { CloudIcon } from '../icons'

interface Props {
  state: DeployState | null
  loading: boolean
  refreshing: boolean
  onRefresh: () => void
}

/** The deployment ladder: what every environment runs, in promotion order.
 *
 *  Everything here comes from `intropy deploy status`, and the sentences it
 *  computed are rendered as served. Nothing is inferred: an environment with no
 *  readable overlay says why, and a lookup that failed says so as a statement
 *  about the lookup rather than about the integration. */
export function Deployment({ state, loading, refreshing, onRefresh }: Props) {
  if (loading && !state) {
    return (
      <Section title="Deployment" icon={CloudIcon}>
        <p className="muted">Reading deployment state…</p>
      </Section>
    )
  }
  if (!state) return null

  return (
    <Section title="Deployment" icon={CloudIcon}>
      {state.error ? (
        // The command's own message, unedited. It already names every way to
        // resolve the problem, and none of these is evidence about whether the
        // integration is deployed.
        <p className="deploy-error">{state.error}</p>
      ) : state.status ? (
        <Ladder status={state.status} />
      ) : (
        <p className="muted">No deployment state.</p>
      )}
      <Provenance state={state} refreshing={refreshing} onRefresh={onRefresh} />
    </Section>
  )
}

function Ladder({ status }: { status: StatusResult }) {
  const rows = status.environments ?? []
  // ArgoCD is the only source for these two, and an empty column would read as
  // unhealthy. When none of it was read, say so once instead.
  const argocdRead = rows.some((e) => e.syncStatus || e.healthStatus)

  return (
    <>
      <p className={`deploy-verdict${status.consistent ? ' agrees' : ''}`}>{status.summary}</p>

      {rows.length === 0 ? (
        <p className="muted">This component declares no environments.</p>
      ) : (
        <table className="deploy-table">
          <thead>
            <tr>
              <th>Environment</th>
              <th>Release</th>
              <th>Image</th>
              <th>Age</th>
              {argocdRead && (
                <>
                  <th>Sync</th>
                  <th>Health</th>
                </>
              )}
            </tr>
          </thead>
          <tbody>
            {rows.map((env) => (
              <Row key={env.environment} env={env} argocdRead={argocdRead} />
            ))}
          </tbody>
        </table>
      )}

      {!argocdRead && rows.length > 0 && (
        <p className="muted deploy-aside">
          ArgoCD was not read, so sync and health are unknown — this says nothing
          about what the overlays pin.
        </p>
      )}

      {status.notes?.length ? (
        <ul className="deploy-notes">
          {status.notes.map((note) => (
            <li key={note}>{note}</li>
          ))}
        </ul>
      ) : null}
    </>
  )
}

function Row({ env, argocdRead }: { env: EnvironmentStatus; argocdRead: boolean }) {
  const span = argocdRead ? 5 : 3

  return (
    <tr className={env.onboarded ? undefined : 'not-onboarded'}>
      <th>
        {env.environment}
        {env.syncPolicy === 'manual' && <span className="deploy-tag">manual</span>}
        {/* For a manual environment this is an unspent gate at rest, not a
            fault, so it is never styled as an error. */}
        {env.pending && <span className="deploy-tag waiting">waiting</span>}
      </th>
      {env.onboarded ? (
        <>
          <td>{releaseCell(env)}</td>
          <td>
            <Pins env={env} />
          </td>
          <td>{ageCell(env)}</td>
          {argocdRead && (
            <>
              <td>{env.syncStatus || NONE}</td>
              <td>{env.healthStatus || NONE}</td>
            </>
          )}
        </>
      ) : (
        // Never omit the row: an environment the component declares but that
        // cannot be read is the fact an operator most needs to see.
        <td className="muted" colSpan={span}>
          {env.reason || 'no readable overlay here'}
        </td>
      )}
    </tr>
  )
}

/** Every declared image, not just the first. The terminal shows one because a
 *  table row has no space for more and has to apologise for it in a note; this
 *  has the room. */
function Pins({ env }: { env: EnvironmentStatus }) {
  const pins = env.pins ?? []
  if (pins.length === 0) return <>{NONE}</>

  return (
    <ul className="deploy-pins">
      {pins.map((pin) => (
        <li key={pin.image}>
          <span className="deploy-image">{shortImage(pin.image)}</span>
          {pin.digest ? (
            <span title={pin.digest}>{shortDigest(pin.digest)}</span>
          ) : pin.tag ? (
            // A tag can change what runs without a deployment, which is the
            // whole reason deploy pins digests.
            <span className="deploy-unpinned" title={`pinned to the tag ${pin.tag}, not a digest`}>
              :{pin.tag}
            </span>
          ) : (
            <span className="muted">{NONE}</span>
          )}
        </li>
      ))}
    </ul>
  )
}

function Provenance({ state, refreshing, onRefresh }: Omit<Props, 'loading'>) {
  return (
    <div className="deploy-foot">
      <div className="deploy-foot-text">
        {state?.readAt && <span className="muted">read {readAge(state.readAt)}</span>}
        {state?.diagnostics?.length ? (
          <ul className="deploy-diagnostics">
            {state.diagnostics.map((d) => (
              <li key={d}>{d}</li>
            ))}
          </ul>
        ) : null}
      </div>
      <button
        type="button"
        className="flow-refresh"
        onClick={onRefresh}
        disabled={refreshing}
        title="Re-run deploy status for this integration"
      >
        {refreshing ? 'Refreshing…' : 'Refresh'}
      </button>
    </div>
  )
}

/** What the terminal prints in an empty cell. */
const NONE = '—'

/** releaseCell mirrors the command: an environment deployed from a commit has no
 *  release but still has something true to say, and the `@` prefix is what keeps
 *  the commit from being misread as a version. */
function releaseCell(env: EnvironmentStatus): string {
  if (env.release) return env.release
  if (env.sourceCommit) return `@${env.sourceCommit.slice(0, 7)}`
  return NONE
}

function ageCell(env: EnvironmentStatus): string {
  return env.deployedAt ? humanAge(Date.now() - Date.parse(env.deployedAt)) : NONE
}

function readAge(readAt: string): string {
  const ms = Date.now() - Date.parse(readAt)
  return Number.isNaN(ms) ? 'just now' : `${humanAge(ms)} ago`
}

/** humanAge mirrors the command at one unit, truncating rather than rounding:
 *  119 minutes is "1h", never "2h". A deployment reading as older than it is
 *  would be taken for a change someone else already reviewed. */
function humanAge(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return '<1m'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 48) return `${hours}h`
  return `${Math.floor(hours / 24)}d`
}

/** shortDigest mirrors the command character for character, so a digest read
 *  here is the same string deploy and promote print. */
function shortDigest(digest: string): string {
  const prefix = 'sha256:'
  const hex = digest.startsWith(prefix) ? digest.slice(prefix.length) : null
  return hex && hex.length > 12 ? prefix + hex.slice(0, 12) : digest
}

/** shortImage drops the registry host so the column reads as a component name,
 *  keeping the last two path segments — enough to tell two images apart. */
function shortImage(image: string): string {
  const parts = image.split('/')
  return parts.length <= 2 ? image : parts.slice(-2).join('/')
}

