package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// runRequest is the POST body for /api/templates/{name}/run: which values to
// scaffold with, and under what name.
type runRequest struct {
	// Name is required. It sets the template's "name" parameter and, because
	// the dashboard never takes an arbitrary output dir, becomes the output
	// directory under the workspace root.
	Name string `json:"name"`
	// Values are the form's answers, layered over the template's defaults.
	Values map[string]any `json:"values,omitempty"`
}

// runResult mirrors deployState: the command's own outcome passed through
// unchanged, so the dashboard cannot claim something `int create` would not.
type runResult struct {
	// Result is template.Create's machine-readable summary, verbatim. Absent
	// when the run failed — only Result says what was scaffolded.
	Result *template.CreateResult `json:"result,omitempty"`

	// Error is the command's refusal, verbatim — a missing required value, a
	// name that fails validation, an output directory that is not empty. None
	// of these is restated here; the message already names how to resolve it.
	Error string `json:"error,omitempty"`

	// Diagnostics is what the command wrote to stderr, one entry per line:
	// the release it fetched, the directory it created, and the skills hint
	// NoInput prints. Provenance for what Result shows, not a failure.
	Diagnostics []string `json:"diagnostics,omitempty"`

	// RanAt is when the command ran, so a reader can tell how current this is.
	RanAt time.Time `json:"ranAt"`
}

// templateRunner scaffolds one template. Like deployProvider it never returns
// a Go error to the handler: a run that cannot complete comes back with Error
// set, because "we could not scaffold" and "nothing was created" must not
// render the same. Which of the two it was is Create's business to say.
type templateRunner func(ctx context.Context, templateName string, req runRequest) runResult

// createRunner is the default runner: it executes template.Create in-process,
// exactly as `int create` does, and passes the outcome through.
//
// Calling the command rather than rendering here is deliberate — Create owns
// every refusal that matters (schema validation, a non-empty output dir, a
// missing required parameter), and each is a case where the honest answer is
// already written down. A second implementation would have to get all of them
// right again.
//
// The write surface is narrow by design: NoInput so a web request never hangs
// on a stdin prompt (a missing value returns a clean error instead), Force
// unset so a non-empty directory is always refused, and the output is always
// <root>/<name> — the dashboard takes no --out-dir and no values files.
//
// With NoInput set, `int create`'s skills step does not install the agent
// skills collection; it prints a hint naming the command to run later. That
// line lands in Diagnostics, so the run result still says how to finish the
// job — the confirmed skip-with-hint behaviour.
func createRunner(root, version string) templateRunner {
	userAgent := "intropy-cli/" + version
	return func(ctx context.Context, templateName string, req runRequest) runResult {
		res := runResult{RanAt: time.Now()}

		if err := template.ValidateTemplateName(req.Name); err != nil {
			res.Error = err.Error()
			return res
		}

		values := map[string]any{}
		for k, v := range req.Values {
			values[k] = v
		}
		values["name"] = req.Name

		var out, logs bytes.Buffer
		err := template.Create(ctx, template.CreateOptions{
			Template:   templateName,
			OutputDir:  filepath.Join(root, req.Name),
			Version:    version,
			SetValues:  values,
			NoInput:    true,
			Force:      false,
			OutputJSON: "-",
			Stdin:      nil,
			Stdout:     &out,
			Stderr:     &logs,
			UserAgent:  userAgent,
		})
		res.Diagnostics = diagnosticLines(logs.String())
		if err != nil {
			res.Error = err.Error()
			return res
		}

		var created template.CreateResult
		if err := json.Unmarshal(out.Bytes(), &created); err != nil {
			// Create succeeded but printed something this cannot read — a
			// version skew rather than anything about the scaffold.
			res.Error = fmt.Sprintf("read create output: %v", err)
			return res
		}
		res.Result = &created
		return res
	}
}

