// providers are the request-independent sources the API reads beyond the
// workspace's own files: what a system host declares about its topology, what
// the GitOps repository says is deployed, and what the template library
// publishes. Each runs a command or a fetch, so each is injected as function
// values that tests replace.
type providers struct {
	topology topologyProvider
	deploy   deployProvider
	tmpl     templateProviders
}

// templateProviders are the template library operations the Templates tab
// uses. List and Describe hit the GitHub API; run scaffolds. All three are
// function values so a test can stub the library without a network.
type templateProviders struct {
	list     func(ctx context.Context, version string) (*template.ListResult, error)
	describe func(ctx context.Context, name, version string) (*template.DescribeResult, error)
	run      templateRunner
}

