	// depMu guards the cached deployment state, keyed by root-relative path.
	// Reading it refreshes a shared GitOps checkout under an exclusive lock, so
	// unlike the topology this is cached per integration and computed only for
	// the ones actually asked about.
	depMu     sync.Mutex
	depStates map[string]deployState

	// tmplMu serializes template list, describe, and run. All three fetch from
	// the GitHub API (describe and run pull a full tarball), and serializing
	// keeps the dashboard under the unauthenticated rate limit and the tarball
	// temp dirs from interleaving. It also guards the list/detail caches.
	tmplMu       sync.Mutex
	tmplLoaded   bool
	tmplList     *template.ListResult
	tmplDetails  map[string]*template.DescribeResult
	tmplTemplate string
}

