	mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
	// Templates tab. GET reads the cached library view; POST on /refresh
	// re-lists, and POST on /run scaffolds. The verb carries the meaning, as
	// with deploy: a {name} segment has to precede the action.
	mux.HandleFunc("GET /api/templates", api.listTemplates)
	mux.HandleFunc("POST /api/templates/refresh", api.refreshTemplates)
	mux.HandleFunc("GET /api/templates/{name}", api.getTemplate)
	mux.HandleFunc("POST /api/templates/{name}/run", api.runTemplate)
	mux.Handle("/", static)
	return mux, nil
}

// tmplVersion resolves which library release a template request targets: the
// ?version= query param wins, then the dashboard-wide default, then latest
// (empty). It mirrors --template-version on the CLI.
func (s *apiServer) tmplVersion(r *http.Request) string {
	if v := r.URL.Query().Get("version"); v != "" {
		return v
	}
	return s.tmplTemplate
}

// listTemplates serves the cached template library listing, computing it on
// the first request. The list is a network read (resolve tag + list dirs), so
// it is cached like the topology; POST /api/templates/refresh recomputes.
func (s *apiServer) listTemplates(w http.ResponseWriter, r *http.Request) {
	s.writeTemplateList(w, r, false)
}

// refreshTemplates re-lists the library and returns the fresh result — how a
// newly published template shows up without restarting the dashboard.
func (s *apiServer) refreshTemplates(w http.ResponseWriter, r *http.Request) {
	s.writeTemplateList(w, r, true)
}

func (s *apiServer) writeTemplateList(w http.ResponseWriter, r *http.Request, force bool) {
	result, err := s.cachedTemplateList(r.Context(), s.tmplVersion(r), force)
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// cachedTemplateList returns the library listing — computed on first use or
// when force is set, reused otherwise. Concurrent requests share one fetch.
func (s *apiServer) cachedTemplateList(ctx context.Context, version string, force bool) (*template.ListResult, error) {
	s.tmplMu.Lock()
	defer s.tmplMu.Unlock()
	if !s.tmplLoaded || force || version != s.tmplListVersion {
		result, err := s.tmpl.list(ctx, version)
		if err != nil {
			return nil, err
		}
		s.tmplList, s.tmplLoaded, s.tmplListVersion = result, true, version
	}
	return s.tmplList, nil
}

// getTemplate serves one template's manifest plus its ordered fields, cached
// per name so the form does not re-pull the tarball on every selection.
func (s *apiServer) getTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	detail, err := s.cachedTemplateDetail(r.Context(), name, s.tmplVersion(r))
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, detail)
}

func (s *apiServer) cachedTemplateDetail(ctx context.Context, name, version string) (*template.DescribeResult, error) {
	s.tmplMu.Lock()
	defer s.tmplMu.Unlock()
	if s.tmplDetails == nil {
		s.tmplDetails = map[string]*template.DescribeResult{}
	}
	if d, ok := s.tmplDetails[name]; ok {
		return d, nil
	}
	d, err := s.tmpl.describe(ctx, name, version)
	if err != nil {
		return nil, err
	}
	s.tmplDetails[name] = d
	return d, nil
}

// runTemplate scaffolds one template into <root>/<name>. This is the
// dashboard's only mutation: it never runs from a GET, is serialized through
// tmplMu, and passes Create's outcome — success or refusal — through verbatim.
func (s *apiServer) runTemplate(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	var req runRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid run request: "+err.Error())
		return
	}
	if strings.TrimSpace(req.Name) == "" {
		writeError(w, http.StatusBadRequest, "name is required")
		return
	}

	result := s.runSerialized(r.Context(), name, req)
	// A scaffolded integration should appear in the catalog without a restart.
	// The catalog reads local disk on every request, so nothing is cached here
	// to invalidate — the next /api/integrations call already sees it.
	writeJSON(w, http.StatusOK, result)
}

// runSerialized runs the scaffold under tmplMu so two runs (or a run and a
// tarball fetch) never interleave. The run is bounded by runTimeout: it can
// download a tarball and render, so it gets longer than deploy's minute.
func (s *apiServer) runSerialized(ctx context.Context, name string, req runRequest) runResult {
	s.tmplMu.Lock()
	defer s.tmplMu.Unlock()
	ctx, cancel := context.WithTimeout(ctx, runTimeout)
	defer cancel()
	return s.tmpl.run(ctx, name, req)
}

func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
